}

.wiw-chip-add {
  border: none;
  background: none;
  color: var(--SmartThemeEmColor);
  cursor: pointer;
  padding: 0 0.15rem;
}
.wiw-chip-add:hover {
  color: var(--SmartThemeQuoteColor);
}

.wiw-image-view img {
  max-width: 100%;
  max-height: 70vh;
  border: 1px solid var(--SmartThemeBorderColor);
  border-radius: 8px;
}
.wiw-image-view figcaption {
  margin-top: 0.4rem;
  color: var(--SmartThemeEmColor);
  font-style: italic;
}

.wiw-assistant {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.wiw-assistant-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}

.wiw-mock-note {
  margin: 0;
  padding: 0.2rem 0.5rem;
  border: 1px dashed var(--SmartThemeEmColor);
  border-radius: 6px;
  color: var(--SmartThemeEmColor);
  font-size: 0.8em;
  text-align: center;
  text-transform: uppercase;
  flex: 1 1 auto;
}

.wiw-bubble {
  padding: 0.45rem 0.6rem;
  border: 1px solid var(--SmartThemeBorderColor);
  border-radius: 8px;
  background: var(--SmartThemeBlurTintColor);
}
.wiw-bubble .wiw-bubble-text {
  margin: 0 0 0.2rem;
}

.wiw-bubble-user {
  border-color: var(--SmartThemeQuoteColor);
}

.wiw-proposals {
  margin-top: 0.4rem;
  padding: 0.45rem;
  border: 1px solid var(--SmartThemeQuoteColor);
  border-radius: 6px;
}

.wiw-proposal-list {
  margin: 0 0 0.4rem;
  padding: 0;
  list-style: none;
}

.wiw-proposal-item {
  padding: 0.4rem;
  border: 1px solid var(--SmartThemeBorderColor);
  border-radius: 6px;
  margin-bottom: 0.4rem;
}

.wiw-proposal-accepted {
  opacity: 0.75;
  border-color: var(--okGreen70a);
}

.wiw-proposal-denied {
  opacity: 0.55;
  border-color: var(--crimson70a);
}

.wiw-proposal-row {
  display: flex;
  align-items: baseline;
  gap: 0.4rem;
  margin-bottom: 0.3rem;
}

.wiw-proposal-op-icon {
  flex: 0 0 auto;
  color: var(--SmartThemeEmColor);
}

.wiw-proposal-summary {
  flex: 1 1 auto;
  min-width: 0;
}

.wiw-decision {
  font-size: 0.72em;
  text-transform: uppercase;
  padding: 0 0.3rem;
  border-radius: 4px;
  border: 1px solid var(--SmartThemeBorderColor);
}

.wiw-decision-accepted {
  border-color: var(--okGreen70a);
  color: var(--okGreen70a);
}

.wiw-decision-denied {
  border-color: var(--crimson70a);
  color: var(--crimson70a);
}

.wiw-proposal-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.wiw-modal {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: color-mix(in srgb, #000 45%, transparent);
  backdrop-filter: blur(var(--SmartThemeBlurStrength));
  z-index: 50;
}

.wiw-modal-card {
  display: flex;
  flex-direction: column;
  width: min(92vw, 1100px);
  height: min(85vh, 900px);
  padding: 0.6rem;
  border: 1px solid var(--SmartThemeBorderColor);
  border-radius: 8px;
  background: var(--SmartThemeChatTintColor);
  color: var(--SmartThemeBodyColor);
}

.wiw-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin-bottom: 0.5rem;
}

.wiw-modal-title {
  font-weight: 600;
}

.wiw-diff {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.4rem;
  flex: 1 1 auto;
  min-height: 0;
}

.wiw-diff-pane {
  border: 1px solid var(--SmartThemeBorderColor);
  border-radius: 6px;
  overflow-y: auto;
  min-width: 0;
}

.wiw-diff-pane-title {
  position: sticky;
  top: 0;
  padding: 0.15rem 0.5rem;
  background: var(--SmartThemeBlurTintColor);
  font-size: 0.78em;
  font-weight: 600;
  text-transform: uppercase;
  z-index: 1;
}

.wiw-diff-line {
  min-height: 1.1em;
}
.wiw-diff-line pre {
  margin: 0;
  padding: 0.05rem 0.5rem;
  font-family: var(--monoFontFamily, monospace);
  font-size: 0.8em;
  white-space: pre-wrap;
  word-break: break-word;
}
.wiw-diff-line.wiw-diff-removed pre {
  background: var(--crimson70a);
}
.wiw-diff-line.wiw-diff-added pre {
  background: var(--okGreen70a);
}
.wiw-diff-line.wiw-diff-empty pre {
  opacity: 0.3;
}

.wiw-sheet {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  top: auto;
  max-height: calc(100% - var(--topBarBlockSize, 40px));
  display: flex;
  animation: wiw-sheet-in 0.22s ease-out;
  flex-direction: column;
  border: 1px solid var(--SmartThemeBorderColor);
  border-radius: 12px 12px 0 0;
  box-shadow: 0 -8px 30px var(--SmartThemeShadowColor);
  background: var(--SmartThemeBlurTintColor);
  backdrop-filter: blur(var(--SmartThemeBlurStrength));
  z-index: 100;
}
.wiw-sheet.wiw-sheet-full {
  border-radius: 0;
}

.wiw-sheet-bar {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.4rem 0.6rem 0.2rem;
  flex: 0 0 auto;
  touch-action: none;
}

.wiw-sheet-handle {
  flex: 1 1 auto;
  height: 6px;
  border-radius: 3px;
  background: var(--SmartThemeShadowColor);
  box-shadow: 0 0 8px var(--SmartThemeShadowColor);
  cursor: grab;
}
.wiw-sheet-handle:active {
  cursor: grabbing;
}

.wiw-sheet-content {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  padding: 0 0.6rem 0.6rem;
}

.wiw-guide {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: color-mix(in srgb, #000 45%, transparent);
  backdrop-filter: blur(var(--SmartThemeBlurStrength));
  z-index: 40;
}

.wiw-guide-card {
  max-width: 42rem;
  max-height: 85%;
  overflow-y: auto;
  padding: 1rem 1.2rem;
  border: 1px solid var(--SmartThemeBorderColor);
  border-radius: 8px;
  background: var(--SmartThemeChatTintColor);
  color: var(--SmartThemeBodyColor);
  box-shadow: 0 8px 30px var(--SmartThemeShadowColor);
}

.wiw-guide-title {
  margin-top: 0;
}

.wiw-guide-list {
  padding-left: 1.2rem;
}
.wiw-guide-list li {
  margin-bottom: 0.5rem;
}

.wiw-guide-note {
  color: var(--SmartThemeEmColor);
  font-style: italic;
}

@media (max-width: 900px) {
  .wiw-region-tree,
  .wiw-region-editor,
  .wiw-region-assistant,
  .wiw-splitter,
  .wiw-content-splitter {
    display: none;
  }
  .wiw-content-body {
    flex-direction: column;
  }
  .wiw-content-textarea {
    min-height: 28vh;
  }
  .wiw-md-preview {
    border-left: none;
    border-top: 1px solid var(--SmartThemeBorderColor);
    max-height: 40vh;
  }
  .wiw-field-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .wiw-field {
    grid-column: span 1 !important;
  }
  .wiw-field.wiw-field-wide {
    grid-column: span 2 !important;
  }
  .wiw-diff {
    grid-template-columns: 1fr;
  }
  .wiw-guide {
    position: fixed;
  }
}
.wiw-entry-header {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.4rem;
}

.wiw-entry-state {
  flex: 0 0 auto;
  border: 1px solid var(--SmartThemeBorderColor);
  border-radius: 6px;
  background: var(--SmartThemeBlurTintColor);
  color: var(--SmartThemeQuoteColor);
  padding: 0.45rem 0.55rem;
  cursor: pointer;
  font-size: 1.05em;
}
.wiw-entry-state:hover {
  border-color: var(--SmartThemeQuoteColor);
}
.wiw-entry-state.wiw-entry-state-disabled {
  color: var(--SmartThemeEmColor);
  opacity: 0.8;
}

.wiw-entry-title {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  min-width: 0;
}
.wiw-entry-title input {
  width: 100%;
  padding: 0.15rem 0.45rem;
  border: 1px solid var(--SmartThemeBorderColor);
  border-radius: 4px;
  background: var(--SmartThemeBlurTintColor);
  color: var(--SmartThemeBodyColor);
  font-size: 1.05em;
  font-weight: 600;
}

.wiw-editor-actions {
  display: flex;
  gap: 0.3rem;
  flex: 0 0 auto;
}

.wiw-strategy {
  display: inline-flex;
  gap: 0.25rem;
}

.wiw-strategy-option {
  flex: 1 1 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.2rem 0.45rem;
  border: 1px solid var(--SmartThemeBorderColor);
  border-radius: 4px;
  background: transparent;
  color: var(--SmartThemeEmColor);
  cursor: pointer;
  font-size: 0.95em;
}
.wiw-strategy-option:hover {
  border-color: var(--SmartThemeQuoteColor);
}

.wiw-strategy-active {
  border-color: var(--SmartThemeQuoteColor);
  color: var(--SmartThemeQuoteColor);
  background: var(--SmartThemeBlurTintColor);
}

.wiw-toggle-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.18rem 0.45rem;
  border: 1px solid var(--SmartThemeBorderColor);
  border-radius: 4px;
  background: transparent;
  color: var(--SmartThemeEmColor);
  font-size: 0.85em;
  cursor: pointer;
  white-space: nowrap;
  max-width: 100%;
}
.wiw-toggle-chip span {
  overflow: hidden;
  text-overflow: ellipsis;
}
.wiw-toggle-chip:hover {
  border-color: var(--SmartThemeQuoteColor);
}

.wiw-toggle-on {
  border-color: var(--SmartThemeQuoteColor);
  color: var(--SmartThemeQuoteColor);
  background: var(--SmartThemeBlurTintColor);
}

.wiw-field-chip {
  justify-content: flex-start;
}

@keyframes wiw-sheet-in {
  from {
    transform: translateY(12%);
    opacity: 0.6;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
